import com.mushafi.app.*;
import com.sun.net.httpserver.*;
import java.io.*;import java.net.*;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class DownloaderChecks {
 static void need(boolean value,String message){if(!value)throw new AssertionError(message);}
 public static void main(String[]args)throws Exception{
 byte[] data=new byte[10*1024*1024];new Random(17).nextBytes(data);String sha=AppUpdatePolicy.hex(MessageDigest.getInstance("SHA-256").digest(data));AppUpdatePolicy release=new AppUpdatePolicy(158,"3.1.8",23,AppUpdatePolicy.ORIGIN+"/download/Mushafi-3.1.8.apk",sha,data.length);
 AtomicBoolean ranged=new AtomicBoolean(true),truncate=new AtomicBoolean(true),badRange=new AtomicBoolean(false);AtomicInteger active=new AtomicInteger(),max=new AtomicInteger(),requests=new AtomicInteger();List<Long> offsets=Collections.synchronizedList(new ArrayList<>());ExecutorService serverThreads=Executors.newCachedThreadPool();HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.setExecutor(serverThreads);
 server.createContext("/file",exchange->{try{exchange.getResponseHeaders().add("Content-Length",String.valueOf(data.length));if(ranged.get())exchange.getResponseHeaders().add("Accept-Ranges","bytes");if(exchange.getRequestMethod().equals("HEAD")){exchange.sendResponseHeaders(200,-1);return;}int count=active.incrementAndGet();max.accumulateAndGet(count,Math::max);requests.incrementAndGet();try{String range=exchange.getRequestHeaders().getFirst("Range");int start=0,end=data.length-1,status=200;if(range!=null&&ranged.get()){String[] values=range.substring(6).split("-");start=Integer.parseInt(values[0]);end=Integer.parseInt(values[1]);offsets.add((long)start);status=206;exchange.getResponseHeaders().set("Content-Range","bytes "+(badRange.get()?start+1:start)+"-"+end+"/"+data.length);}int length=end-start+1;exchange.getResponseHeaders().set("Content-Length",String.valueOf(length));exchange.sendResponseHeaders(status,length);boolean shortBody=truncate.getAndSet(false);int until=shortBody?start+length/2:end+1;try(OutputStream out=exchange.getResponseBody()){for(int at=start;at<until;at+=65536){out.write(data,at,Math.min(65536,until-at));out.flush();try{Thread.sleep(10);}catch(InterruptedException e){Thread.currentThread().interrupt();break;}}}}finally{active.decrementAndGet();}}catch(IOException ignored){}finally{exchange.close();}});server.start();
 AppUpdateDownloader.ConnectionFactory factory=url->(HttpURLConnection)new URL("http://127.0.0.1:"+server.getAddress().getPort()+"/file").openConnection();File root=Files.createTempDirectory("mushafi-download-test").toFile();
 try{File parallel=new File(root,"parallel");AppUpdateDownloader first=new AppUpdateDownloader(release,parallel,factory,(n,total,speed)->{});File result=first.download();release.verify(result);need(max.get()>=2,"parallel transfers did not overlap");need(requests.get()>=4,"truncated range did not retry");first.verified();System.out.println("PASS parallel ranges overlap, interrupted range retries and full checksum");
 File resume=new File(root,"resume");AtomicReference<AppUpdateDownloader> current=new AtomicReference<>();AtomicBoolean stopped=new AtomicBoolean();AppUpdateDownloader cancelled=new AppUpdateDownloader(release,resume,factory,(n,total,speed)->{if(n>1024*1024&&stopped.compareAndSet(false,true))current.get().cancel();});current.set(cancelled);try{cancelled.download();throw new AssertionError("Cancel ignored");}catch(Exception expected){need(stopped.get(),"unexpected pre-cancel failure");}offsets.clear();AtomicLong initial=new AtomicLong(-1);AppUpdateDownloader resumed=new AppUpdateDownloader(release,resume,factory,(n,total,speed)->initial.compareAndSet(-1,n));release.verify(resumed.download());need(initial.get()>0,"saved bytes were not restored");need(offsets.stream().anyMatch(n->n>0&&n%((data.length+2)/3)!=0),"partial range did not resume at saved offset");System.out.println("PASS cancel preserves chunks; next downloader resumes from saved offsets");
 ranged.set(false);AppUpdateDownloader single=new AppUpdateDownloader(release,new File(root,"single"),factory,(n,total,speed)->{});release.verify(single.download());System.out.println("PASS sequential fallback when server does not advertise ranges");
 ranged.set(true);badRange.set(true);try{new AppUpdateDownloader(release,new File(root,"invalid"),factory,(n,total,speed)->{}).download();throw new AssertionError("Wrong Content-Range accepted");}catch(Exception expected){}System.out.println("PASS invalid Content-Range rejected");
 }finally{server.stop(0);serverThreads.shutdownNow();AppUpdateDownloader.delete(root);}
 }
}
